import { describe, it, expect } from 'vitest'
import { groupOpenTasksByAssignee } from './people-load.js'

// X2：wrapped 已收尾不计入 open 负载（isOpen 排除 wrapped）。

const PROJECTS = [{ id: 'p-0001', name: '验证项目' }]

function task(over: Partial<Parameters<typeof groupOpenTasksByAssignee>[0][number]> & { id: string }) {
  return {
    projectId: 'p-0001',
    title: over.id,
    assignee: '李工',
    status: 'todo',
    priority: 'P1',
    progress: 0,
    dueDate: null,
    ...over,
  }
}

describe('groupOpenTasksByAssignee X2 wrapped 口径', () => {
  it('wrapped 任务不进 open 分组；正常 open 任务照常计入', () => {
    const report = groupOpenTasksByAssignee([
      task({ id: 'w-1', status: 'wrapped', dueDate: '2026-10-10' }),
      task({ id: 'o-1', status: 'in_progress', progress: 30, dueDate: '2026-10-20' }),
    ], PROJECTS, { today: '2026-10-18' })
    const li = report.people.find(p => p.key === '李工')
    expect(li?.openTotal).toBe(1)
    expect(li?.tasks.map(t => t.id)).toEqual(['o-1'])
    expect(report.unassigned).toBeNull()
  })
})
import { describe, it, expect } from 'vitest'
import { loadScale } from './people-scale.js'

// G-B 人员负载同刻度：scaleMax 含未分配桶；过滤/筛选不缩尺。

describe('loadScale 同刻度', () => {
  it('空分配 + 阈值/未分配为 0 → 下限 8，刻度 0..8 步长 2', () => {
    const { maxX, ticks } = loadScale([], 0, 0)
    expect(maxX).toBe(8)
    expect(ticks).toEqual([0, 2, 4, 6, 8])
  })

  it('未分配桶 open 计入上限（即使已分配都很小）→ 未分配驱动 maxX', () => {
    const { maxX } = loadScale([3, 2], 9, 5)
    // rawMax=9 → ceil((9+2)/2)*2=12
    expect(maxX).toBe(12)
  })

  it('过滤/筛选不缩尺：阈值仍计入，maxX 不随可见人数收缩到阈值以下', () => {
    const { maxX } = loadScale([1], 0, 20)
    // rawMax=20 → ceil(22/2)*2=22
    expect(maxX).toBe(22)
  })

  it('向上取整到 2 的倍数并 +2 留余量', () => {
    expect(loadScale([7], 0, 0).maxX).toBe(10) // rawMax=7 → ceil(9/2)*2=10
    expect(loadScale([8], 0, 0).maxX).toBe(10) // rawMax=8 → ceil(10/2)*2=10
  })
})
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { createRequire } from 'node:module'

const pkg = '/Users/bytedance/Projects/dsh-pm/pm-tool/packages/dsh-pm-tool'
const out = '/tmp/people-axis-slots-capacity-developer-20261023'
const frozen = `${out}/frozen`
const require = createRequire(`${pkg}/package.json`)
const ts = require('typescript')
const sha = b => crypto.createHash('sha256').update(b).digest('hex')
const seeds = [
  'src/client/views/people.tsx',
  'src/client/views/people-scale.test.ts',
  'src/core/people-load.test.ts',
  'src/client/assets.d.ts',
]

if (process.argv[2] === 'freeze') {
  const visited = new Set()
  const records = []
  function visit(rel) {
    if (visited.has(rel)) return
    if (!rel.startsWith('src/') || rel.includes('../')) throw Error(`outside narrow src: ${rel}`)
    visited.add(rel)
    if (visited.size > 60) throw Error('narrow dependency limit exceeded')
    const original = `${pkg}/${rel}`
    const bytes = fs.readFileSync(original)
    const dest = `${frozen}/${rel}`
    fs.mkdirSync(path.dirname(dest), { recursive: true })
    fs.writeFileSync(dest, bytes)
    records.push({ original, frozen: dest, bytes: bytes.length, sha256: sha(bytes) })
    if (!/\.(ts|tsx)$/.test(rel)) return
    for (const { fileName } of ts.preProcessFile(bytes.toString(), true, true).importedFiles) {
      if (!fileName.startsWith('.')) continue
      const requested = path.posix.normalize(path.posix.join(path.posix.dirname(rel), fileName.split('?')[0]))
      const candidates = requested.endsWith('.js')
        ? [requested.slice(0, -3) + '.ts', requested.slice(0, -3) + '.tsx', requested.slice(0, -3) + '.d.ts', requested]
        : [requested, requested + '.ts', requested + '.tsx', requested + '/index.ts']
      const resolved = candidates.find(p => fs.existsSync(`${pkg}/${p}`) && fs.statSync(`${pkg}/${p}`).isFile())
      if (!resolved) throw Error(`unresolved frozen relative import ${rel}: ${fileName}`)
      visit(resolved)
    }
  }
  for (const seed of seeds) visit(seed)
  fs.symlinkSync(`${pkg}/node_modules`, `${frozen}/node_modules`, 'dir')
  fs.writeFileSync(`${frozen}/package.json`, JSON.stringify({ private: true, type: 'module' }) + '\n')
  for (const name of ['home', 'tmp', 'cache']) fs.mkdirSync(`${out}/${name}`, { recursive: true })
  fs.writeFileSync(`${out}/frozen-inputs.json`, JSON.stringify({
    createdUtc: new Date().toISOString(),
    dependencyMapping: { from: `${frozen}/node_modules`, readOnlyTarget: `${pkg}/node_modules`, dependencyCopy: false },
    records,
  }, null, 2) + '\n')
  console.log(JSON.stringify({ frozenFiles: records.length, seeds, dependencyCopy: false, srcWalk: 'exact relative imports only' }))
} else if (process.argv[2] === 'check') {
  const inputs = JSON.parse(fs.readFileSync(`${out}/frozen-inputs.json`, 'utf8'))
  for (const r of inputs.records) {
    const b = fs.readFileSync(r.frozen)
    if (b.length !== r.bytes || sha(b) !== r.sha256) throw Error(`frozen input drift ${r.frozen}`)
  }
  const options = {
    target: ts.ScriptTarget.ES2022,
    lib: ['lib.es2023.d.ts', 'lib.dom.d.ts', 'lib.dom.iterable.d.ts'],
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
    strict: true,
    skipLibCheck: true,
    esModuleInterop: true,
    jsx: ts.JsxEmit.ReactJSX,
    noEmit: true,
    types: ['node', 'react'],
    typeRoots: [`${frozen}/node_modules/@types`],
  }
  const program = ts.createProgram([
    `${frozen}/src/client/views/people.tsx`,
    `${frozen}/src/client/assets.d.ts`,
  ], options)
  const diagnostics = ts.getPreEmitDiagnostics(program)
  if (diagnostics.length) {
    console.error(ts.formatDiagnosticsWithColorAndContext(diagnostics, {
      getCanonicalFileName: f => f,
      getCurrentDirectory: () => frozen,
      getNewLine: () => '\n',
    }))
    process.exitCode = 1
  }
  const vitestRequire = createRequire(require.resolve('vitest/package.json'))
  const viteRequire = createRequire(vitestRequire.resolve('vite/package.json'))
  const postcss = viteRequire('postcss')
  postcss.parse(fs.readFileSync(`${frozen}/src/client/views/people.css`, 'utf8'), {
    from: `${frozen}/src/client/views/people.css`,
  })
  console.log(JSON.stringify({
    typescriptVersion: ts.version,
    typeDiagnostics: diagnostics.length,
    cssSyntaxParsed: true,
    productEmit: false,
    uiOrAccessibilityPass: false,
  }))
} else {
  throw Error('expected freeze/check')
}

